def generate_upc_a(payload: str) -> str:
    """
    Takes an 11-digit string payload and appends the correct
    GS1 Modulo-10 check digit to return a valid 12-digit UPC-A barcode.
    """
    if len(payload) != 11 or not payload.isdigit():
        raise ValueError("Payload must be a string of exactly 11 digits.")

    # Convert string into a list of integers
    digits = [int(d) for d in payload]
    check_digit = (10 - ((sum(digits[0::2]) * 3 + sum(digits[1::2])) % 10)) % 10

    return f"{payload}{check_digit}"
